def finiteLift (s : Finset ℤ) : E →L[𝕜] DFJPSum D :=
  ∑ j ∈ s, (lp.singleContinuousLinearMap 𝕜 (DFJPScale D) 2 j).comp
    (DFJPScale.continuousLinearEquiv D j).symm.toContinuousLinearMap

